function removerAcentos(txt) {
  return String(txt).normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function calcularPontos(exercicio, valor) {
  const ex = removerAcentos(String(exercicio).toLowerCase().trim());
  const v = Number(valor);

  if (ex.includes('flex')) {
    if (v >= 32) return 100;
    if (v >= 30) return 90;
    if (v >= 28) return 80;
    if (v >= 26) return 70;
    if (v >= 24) return 60;
    if (v >= 22) return 50;
    if (v >= 20) return 40;
    if (v >= 18) return 30;
    if (v >= 16) return 20;
    if (v >= 14) return 10;
    return 0;
  }

  if (ex.includes('abdom')) {
    if (v >= 42) return 100;
    if (v >= 40) return 90;
    if (v >= 38) return 80;
    if (v >= 36) return 70;
    if (v >= 34) return 60;
    if (v >= 32) return 50;
    if (v >= 30) return 40;
    if (v >= 28) return 30;
    if (v >= 26) return 20;
    if (v >= 24) return 10;
    return 0;
  }

  if (ex.includes('50m') || ex.includes('tiro') || (ex.includes('corrida') && v < 20)) {
    if (v <= 6.75) return 100;
    if (v <= 7.00) return 90;
    if (v <= 7.25) return 80;
    if (v <= 7.50) return 70;
    if (v <= 7.75) return 60;
    if (v <= 8.00) return 50;
    if (v <= 8.25) return 40;
    if (v <= 8.50) return 30;
    if (v <= 8.75) return 20;
    if (v <= 9.00) return 10;
    return 0;
  }

  if (ex.includes('12') || ex.includes('resistencia') || v >= 1000) {
    if (v >= 2800) return 100;
    if (v >= 2700) return 90;
    if (v >= 2600) return 80;
    if (v >= 2500) return 70;
    if (v >= 2400) return 60;
    if (v >= 2300) return 50;
    if (v >= 2200) return 40;
    if (v >= 2100) return 30;
    if (v >= 2000) return 20;
    if (v >= 1900) return 10;
    return 0;
  }

  return 0;
}

const registros = $input.all().map(i => i.json);

const categorias = [
  { label: 'Flexão de Braço', match: ex => ex.includes('flex') },
  { label: 'Abdominal', match: ex => ex.includes('abdom') },
  { label: 'Corrida 50m', match: ex => ex.includes('50m') || ex.includes('tiro') },
  { label: 'Corrida 12min', match: ex => (ex.includes('corrida') && ex.includes('12')) || ex.includes('resistencia') }
];

let pontuacaoTotalAcurada = 0;
let resumoExercicios = [];

for (const cat of categorias) {
  const filtrados = registros.filter(r => {
    const exNorm = removerAcentos(String(r.exercicio).toLowerCase().trim());
    return r.status !== 'falta' && cat.match(exNorm);
  });

  if (filtrados.length > 0) {
    const comPontos = filtrados.map(r => ({ ...r, pontosCalc: calcularPontos(r.exercicio, r.valor) }));
    const melhor = comPontos.reduce((max, r) => (r.pontosCalc > max.pontosCalc ? r : max), comPontos[0]);

    pontuacaoTotalAcurada += melhor.pontosCalc;
    resumoExercicios.push({
      exercicio: cat.label,
      melhor_marca: melhor.valor,
      unidade: melhor.unidade,
      pontos: melhor.pontosCalc,
      sessoes: filtrados.length
    });
  } else {
    resumoExercicios.push({
      exercicio: cat.label,
      melhor_marca: 'Sem treinos',
      pontos: 0,
      sessoes: 0
    });
  }
}

const faltas = registros.filter(r => r.status === 'falta').length;

const porDia = {};
for (const r of registros) {
  const dia = String(r.data).slice(0, 10);
  if (!porDia[dia]) porDia[dia] = { data: dia, treinou: false, pontosDoDia: 0, exercicios: [] };

  if (r.status !== 'falta') {
    const pts = calcularPontos(r.exercicio, r.valor);
    porDia[dia].treinou = true;
    porDia[dia].pontosDoDia += pts;
    porDia[dia].exercicios.push({ exercicio: r.exercicio, valor: r.valor, unidade: r.unidade, pontos: pts });
  }
}
const diasOrdenados = Object.values(porDia).sort((a, b) => a.data.localeCompare(b.data));

return [{
  pontuacao_total: pontuacaoTotalAcurada,
  meta: 210,
  atingiu_meta: pontuacaoTotalAcurada >= 210,
  dias_faltosos: faltas,
  detalhes: resumoExercicios,
  detalhamento_diario: diasOrdenados
}];

const data = $input.first().json;
let texto = `### RELATÓRIO DE DESEMPENHO TAF\n`;
texto += `Pontuação Total Acumulada: ${data.pontuacao_total} / 210 pontos mínimos\n`;
texto += `Atingiu a Meta dos 210 pts? ${data.atingiu_meta ? 'SIM' : 'NÃO'}\n`;
texto += `Dias sem treino na semana (Faltas): ${data.dias_faltosos}\n\n`;

texto += `### MELHOR MARCA DA SEMANA POR EXERCÍCIO:\n`;
for (const ex of data.detalhes) {
  texto += `- ${ex.exercicio}: Melhor marca = ${ex.melhor_marca}${ex.unidade ? ' ' + ex.unidade : ''} (${ex.pontos} pts) | ${ex.sessoes} sessão(ões) na semana\n`;
}

texto += `\n### DETALHAMENTO DIA A DIA:\n`;
for (const dia of data.detalhamento_diario) {
  if (dia.treinou) {
    const lista = dia.exercicios.map(e => `${e.exercicio} = ${e.valor}${e.unidade ? ' ' + e.unidade : ''} (${e.pontos} pts)`).join('; ');
    texto += `- ${dia.data}: TREINOU — ${lista} | Total do dia: ${dia.pontosDoDia} pts\n`;
  } else {
    texto += `- ${dia.data}: FALTA — nenhum treino registrado\n`;
  }
}

return [{ resumo: texto.trim() }];

